require_once __DIR__.'/dashboard-operations.php';
$hasPeople=tableExists('workspace_people');
$people=$db->query("SELECT u.id,u.full_name,u.start_date,u.status".($hasPeople?',p.department,p.job_title,p.avatar_color,p.is_demo':",'General' department,'Team member' job_title,'#b6a2ed' avatar_color,0 is_demo").' FROM users u '.($hasPeople?'LEFT JOIN workspace_people p ON p.user_id=u.id ':'')."WHERE u.role='employee' ORDER BY u.created_at DESC LIMIT 6")->fetchAll();
$demoCount=$hasPeople?(int)$db->query('SELECT COUNT(*) FROM workspace_people WHERE is_demo=1')->fetchColumn():0;
$departments=$hasPeople?$db->query("SELECT p.department,COUNT(*) total FROM workspace_people p JOIN users u ON u.id=p.user_id WHERE u.status='active' AND u.role='employee' GROUP BY p.department ORDER BY total DESC")->fetchAll():[];
$todayAttendance=tableExists('attendance')?(int)$db->query('SELECT COUNT(*) FROM attendance WHERE work_date=CURRENT_DATE')->fetchColumn():0;
$pendingLeave=tableExists('leave_requests')?(int)$db->query("SELECT COUNT(*) FROM leave_requests WHERE status='pending'")->fetchColumn():0;
$jobs=tableExists('job_openings')?(int)$db->query("SELECT COUNT(*) FROM job_openings WHERE status='active'")->fetchColumn():0;
$attendance=[];if(tableExists('attendance')){$attendance=$db->query('SELECT work_date,COUNT(*) total FROM attendance WHERE work_date>=DATE_SUB(CURRENT_DATE,INTERVAL 6 DAY) GROUP BY work_date')->fetchAll(PDO::FETCH_KEY_PAIR);}
$activities=$db->query('SELECT action,created_at FROM audit_log ORDER BY created_at DESC LIMIT 4')->fetchAll();
$monthDays=(int)date('t');$firstDay=(int)date('N',strtotime(date('Y-m-01')));
$colors=['#b29ad9','#e8c5a7','#bed6c8','#b9c8e6','#d9bedb','#cbd4b0'];$totalDept=array_sum(array_column($departments,'total'));$stops=[];$offset=0;foreach($departments as $i=>$department){$end=$offset+($totalDept?100*$department['total']/$totalDept:0);$stops[]=$colors[$i%6].' '.$offset.'% '.$end.'%';$offset=$end;}
pageHead('Overview'); ?>
