<?php renderDashboardOperations($db,$user);?><div class="chart-row"><section class="card"><div class="section-head"><h3>Attendance overview</h3><span>Last 7 days ↗</span></div><div class="chart-body"><div class="attendance-chart" role="img" aria-label="Daily attendance over the last seven days"><?php $max=max(1,...array_values($attendance));for($d=6;$d>=0;$d--):$date=date('Y-m-d',strtotime("-$d days"));$count=(int)($attendance[$date]??0);?><div class="attendance-bar" title="<?=e($date)?>: <?=$count?> checked in" style="height:<?=max(3,120*$count/$max)?>px"></div><?php endfor;?></div><div class="chart-labels"><?php for($d=6;$d>=0;$d--):?><span><?=date('D',strtotime("-$d days"))?></span><?php endfor;?></div></div></section>
